-- See https://wiki.hypr.land/Configuring/Layouts/Dwindle-Layout/ for more
hl.config({
    dwindle = {
        preserve_split = true, -- You probably want this
    },
})

-- See https://wiki.hypr.land/Configuring/Layouts/Master-Layout/ for more
hl.config({
    master = {
        -- Active (master) window takes 60% of the screen; all other windows
        -- share the remaining 40% to the side.
        mfact = 0.6,
        new_status = "master",
        -- New windows become the master by default.
        new_on_top = true,
    },
})

-- Native SCROLL/carousel layout with equal-width columns (50/50 split).
-- 3-finger swipes slide between windows; 4-finger slide between workspaces.
hl.config({
    scrolling = {
        -- With multiple columns each gets the same width -> equal split.
        fullscreen_on_one_column = true,
        -- Default column width (0.5 = each column half of the screen).
        column_width = 0.5,
        -- Preconfigured widths for colresize +/-conf.
        explicit_column_widths = "0.5, 1.0",
        -- 0 = center, 1 = fit: how a focused column is brought into view.
        focus_fit_method = 1,
        -- Direction in which new windows appear and the layout scrolls.
        direction = "right",
        -- Wrap focus at the ends so cycling loops like a carousel.
        wrap_focus = true,
        wrap_swapcol = true,
        -- Follow the focused window automatically so the carousel tracks it.
        follow_focus = true,
    },
})


