-- See https://wiki.hypr.land/Configuring/Basics/Window-Rules/
-- and https://wiki.hypr.land/Configuring/Basics/Workspace-Rules/

-- Example window rules that are useful

local suppressMaximizeRule = hl.window_rule({
    -- Ignore maximize requests from all apps. You'll probably like this.
    name  = "suppress-maximize-events",
    match = { class = ".*" },

    suppress_event = "maximize",
})
-- suppressMaximizeRule:set_enabled(false)

hl.window_rule({
    -- Fix some dragging issues with XWayland
    name  = "fix-xwayland-drags",
    match = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },

    no_focus = true,
})

-- Layer rules also return a handle.
-- local overlayLayerRule = hl.layer_rule({
--     name  = "no-anim-overlay",
--     match = { namespace = "^my-overlay$" },
--     no_anim = true,
-- })
-- overlayLayerRule:set_enabled(false)

-- Enable the blur/vibrancy effect on the wlogout layer (namespace "logout_dialog"),
-- matching the other HyDE blur layers (waybar, rofi, swaync, etc.).
hl.layer_rule({
    name  = "blur-logout-dialog",
    match = { namespace = "logout_dialog" },
    blur  = true,
})

-- Hyprland-run windowrule
hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },

    move  = "20 monitor_h-120",
    float = true,
})

-- scrcpy: floating, centered, aspect preserved by scrcpy itself
-- Do not force size here to avoid distorting phone ratio.
-- Optional fixed 0.5x scale for 1080x2400 phone: size = "540 1200",
-- NOTE: pin removed - pin=true blocks Hyprland fullscreen and breaks scrcpy Alt+f SDL fullscreen.
hl.window_rule({
    name  = "scrcpy-float",
    match = { class = "^scrcpy$" },

    float = true,
    center = true,
})

hl.window_rule({
    name    = "foot-opacity",
    match   = { class = "^foot$" },

    opacity = "1.0 override 1.0 override",
})

-- Autostart: migrated to systemd user/system services (2026-10-10, no uwsm).
-- Previously here (now removed):
--   dbus-update-activation-environment  -> not needed; systemd user env already has
--                                          WAYLAND_DISPLAY/XDG_CURRENT_DESKTOP (verified)
--   gnome-keyring-daemon --start        -> socket-activated gnome-keyring-daemon.service + PAM (sddm)
--   libinput-gestures &                 -> libinput-gestures.service (default.target.wants,
--                                          wrapper derives fresh instance env at exec and
--                                          re-execs on compositor restart)
--   hyprpm reload                       -> hyprpm-reload.service (default.target.wants,
--                                          supervisor poll: keeps enabled plugins loaded
--                                          across boot and compositor restarts)
--   docker restart mongodb              -> container restart policy `unless-stopped` (no launch-time docker cmd)
--   launch-waybar.sh &                  -> waybar-launcher.service (default.target.wants, oneshot
--                                          wrapping launch-waybar.sh -> transient hyde-Hyprland-bar.service)
--   kdeconnectd                         -> kdeconnect-headless.service (default.target)
-- NOTE (no uwsm): graphical-session.target stays inactive (RefuseManualStart, plain
-- `start-hyprland` session), so all user units are bound to default.target instead.
-- waybar.service is intentionally disabled to avoid a duplicate bar next to HyDE's transient unit.
-- No exec-once commands remain; session services start via systemd.
